import { OperationsStore } from '../src/operations.store'

describe('automatic driver assignment', () => {
  it('assigns the available driver nearest to the trip origin', () => {
    const near = {
      id: 'drv-near', name: 'Pedro Ruiz', phone: '1', vehicle: 'Mercedes Sprinter', plate: 'N-1',
      status: 'Disponible' as const, route: 'Sin viaje activo', latitude: 12.1159, longitude: -86.2478,
    }
    const preferredButFar = {
      id: 'drv-preferred', name: 'Carlos Díaz', phone: '2', vehicle: 'VW Caddy', plate: 'N-2',
      status: 'Disponible' as const, route: 'Sin viaje activo', latitude: 12.14, longitude: -86.22,
    }
    const store = Object.create(OperationsStore.prototype) as any
    store.drivers = [near, preferredButFar]
    store.db = {
      exec: jest.fn(),
      prepare: jest.fn((query: string) => ({
        get: (driverName?: string) => query.includes('driver_locations')
          ? { latitude: driverName === 'Pedro Ruiz' ? 12.1159 : 12.14, longitude: driverName === 'Pedro Ruiz' ? -86.2478 : -86.22, updated_at: Date.now(), accuracy: 10, speed_kmh: 0, source: 'app' }
          : undefined,
        run: jest.fn(() => query.includes('UPDATE drivers') ? { changes: 1 } : undefined),
      })),
    }
    store.persistTrip = jest.fn()
    store.recordHistory = jest.fn()

    const trip = {
      id: '#test', client: 'Cliente', driver: 'Sin asignar', origin: 'Origen', destination: 'Destino',
      date: '30 oct', packages: 1, status: 'Pendiente' as const, originLat: 12.1159, originLng: -86.2478,
    }

    store.assignAutomatically(trip)

    expect(trip.driver).toBe('Pedro Ruiz')
    expect(trip.status).toBe('Asignado')
    expect(near.status).toBe('En viaje')
    expect(preferredButFar.status).toBe('Disponible')
  })
})
